INSERT INTO `ai_generated_modules` VALUES (2,1,'SMA Negeri 1 Turen','2026/2027','Ganjil','E','Bilangan Berpangkat','Matematika','Bilangan Berpangkat',4,0,360,'Problem Based Learning','Adiwiyata','menggeneralisasi sifat bilangan berpangkat','Fery Irawan, S.Pd.','199405122022211009','Agus Harianto, M.Pd.','197008222001211008','Turen',NULL,'failed',NULL,NULL,'Gagal memproses hasil AI pada bagian pertemuan 4-4. Coba generate ulang.','2026-07-18 13:21:54','2026-07-18 13:23:00'),(3,1,'SMA Negeri 1 Turen','2026/2027','Ganjil','F','XI','Matematika','Vektor',4,0,360,'Problem Based Learning','Adiwiyata','Melakukan operasi aljabar seperti penjumlahan, pengurangan, perkalian dengan skalar, hingga dot product dan cross product','Fery Irawan, S.Pd.','199405122022211009','Agus Harianto, M.Pd.','197008222001211008','Turen',NULL,'processing','[]','',NULL,'2026-07-19 14:50:52','2026-07-19 14:50:52'),(4,1,'SMA Negeri 1 Turen','2026/2027','Ganjil','F+','XI','Matematika','Vektor',1,1,90,'Problem Based Learning','Adiwiyata','Melakukan operasi aljabar seperti penjumlahan, pengurangan, perkalian dengan skalar, hingga dot product dan cross product','Fery Irawan, S.Pd.','199405122022211009','Agus Harianto, M.Pd.','197008222001211008','Turen',NULL,'completed','[{\"content\": \"<h3>Modul Ajar Matematika</h3><p><b>Sekolah:</b> SMA Negeri 1 Turen</p><p><b>Tahun Ajaran:</b> 2026/2027, Semester Ganjil</p><p><b>Fase:</b> F+, <b>Kelas:</b> XI</p><p><b>Materi:</b> Vektor</p><p><b>Alokasi Waktu:</b> 90 menit (1 pertemuan)</p><p><b>Model Pembelajaran:</b> Problem Based Learning</p><p><b>Integrasi:</b> Adiwiyata</p><p><b>Capaian Pembelajaran:</b> Melakukan operasi aljabar seperti penjumlahan, pengurangan, perkalian dengan skalar, hingga dot product dan cross product.</p><h3>Tujuan Pembelajaran</h3><ul>  <li>Peserta didik dapat mengidentifikasi konsep dasar vektor, besaran, arah, dan notasi vektor.</li>  <li>Peserta didik dapat melakukan operasi penjumlahan dan pengurangan vektor secara geometris dan aljabar.</li>  <li>Peserta didik dapat melakukan operasi perkalian vektor dengan skalar.</li>  <li>Peserta didik dapat memahami konsep dan melakukan perhitungan dasar dot product.</li>  <li>Peserta didik dapat memahami konsep cross product sebagai pengenalan.</li></ul><h3>Langkah Kegiatan Pembelajaran</h3><h4>A. Pendahuluan (15 menit)</h4><ul>  <li>Guru mengucapkan salam, memimpin doa, dan melakukan presensi.</li>  <li>Guru melakukan apersepsi dengan mengingatkan peserta didik tentang besaran skalar dan besaran vektor dalam kehidupan sehari-hari (misalnya, perpindahan, gaya, kecepatan).</li>  <li>Guru memotivasi peserta didik dengan menjelaskan pentingnya konsep vektor dalam berbagai bidang (misalnya, navigasi, fisika, grafika komputer).</li>  <li><b>Integrasi Adiwiyata:</b> Guru mengaitkan penggunaan vektor dalam konteks lingkungan, seperti arah dan kecepatan angin dalam penyebaran polutan atau arah aliran air untuk sistem irigasi di taman sekolah.</li>  <li>Guru menyampaikan tujuan pembelajaran yang akan dicapai pada pertemuan ini.</li></ul><h4>B. Inti (60 menit)</h4><ol>  <li><b>Orientasi Peserta Didik pada Masalah:</b>    <ul>      <li>Guru menyajikan masalah kontekstual yang melibatkan konsep vektor, misalnya: \\\"Seorang siswa berjalan dari gerbang sekolah menuju taman Adiwiyata, kemudian berbelok menuju perpustakaan. Bagaimana kita dapat menentukan total perpindahan siswa tersebut menggunakan konsep vektor?\\\"</li>    </ul>  </li>  <li><b>Mengorganisasikan Peserta Didik untuk Belajar:</b>    <ul>      <li>Peserta didik dibagi menjadi kelompok-kelompok kecil (4-5 orang).</li>      <li>Setiap kelompok menerima Lembar Kerja Peserta Didik (LKPD) yang berisi masalah dan pertanyaan-pertanyaan panduan untuk memecahkan masalah tersebut.</li>    </ul>  </li>  <li><b>Membimbing Penyelidikan Individu maupun Kelompok:</b>    <ul>      <li>Peserta didik berdiskusi dalam kelompok untuk menganalisis masalah, mencari informasi (dari buku teks, internet, atau penjelasan guru), dan merumuskan strategi penyelesaian.</li>      <li>Guru berkeliling, memfasilitasi diskusi, membimbing kelompok yang mengalami kesulitan, dan memastikan setiap anggota kelompok berpartisipasi aktif.</li>      <li>Fokus eksplorasi meliputi: definisi vektor, notasi, operasi penjumlahan dan pengurangan vektor (geometris dan aljabar), perkalian vektor dengan skalar, serta pengenalan konsep dot product dan cross product.</li>    </ul>  </li>  <li><b>Mengembangkan dan Menyajikan Hasil Karya:</b>    <ul>      <li>Setiap kelompok menyusun hasil diskusi dan penyelesaian masalah pada LKPD.</li>      <li>Beberapa perwakilan kelompok diminta untuk mempresentasikan hasil kerja mereka di depan kelas.</li>    </ul>  </li>  <li><b>Menganalisis dan Mengevaluasi Proses Pemecahan Masalah:</b>    <ul>      <li>Guru dan peserta didik bersama-sama menganalisis dan mengevaluasi solusi yang disajikan oleh setiap kelompok.</li>      <li>Guru memberikan penguatan konsep-konsep kunci dan meluruskan miskonsepsi yang mungkin terjadi.</li>    </ul>  </li></ol><h4>C. Penutup (15 menit)</h4><ul>  <li>Guru bersama peserta didik menyimpulkan kembali konsep-konsep penting tentang vektor dan operasi-operasinya.</li>  <li>Guru memberikan umpan balik terhadap proses pembelajaran dan kinerja kelompok.</li>  <li>Guru memberikan penguatan untuk materi yang telah dipelajari dan memberikan motivasi untuk terus berlatih.</li>  <li>Guru mengakhiri pelajaran dengan doa dan salam.</li></ul><h3>Asesmen</h3><ul>  <li><b>Asesmen Diagnostik:</b> Pertanyaan lisan singkat di awal pembelajaran untuk mengecek pemahaman awal tentang besaran vektor.</li>  <li><b>Asesmen Formatif:</b>    <ul>      <li>Observasi selama diskusi kelompok (penilaian sikap: kerja sama, keaktifan, tanggung jawab).</li>      <li>Penilaian LKPD (pemahaman konsep, ketepatan penyelesaian masalah).</li>      <li>Penilaian presentasi kelompok (kemampuan mengkomunikasikan ide).</li>    </ul>  </li></ul><h3>Lembar Kerja Peserta Didik (LKPD)</h3><h4>Eksplorasi Vektor di Lingkungan Sekolah</h4><p><b>Tujuan:</b> Memahami konsep vektor dan operasinya melalui masalah kontekstual.</p><p><b>Masalah 1:</b> Seorang penjaga taman Adiwiyata ingin memindahkan pot bunga besar. Ia menarik pot dengan gaya F1 = (3, 4) N dan temannya mendorong dengan gaya F2 = (2, -1) N.</p><ul>  <li>a. Gambarlah vektor F1 dan F2 pada bidang koordinat.</li>  <li>b. Tentukan vektor resultan (total gaya) F_total = F1 + F2 secara aljabar.</li>  <li>c. Hitunglah besar gaya total yang bekerja pada pot bunga.</li></ul><p><b>Masalah 2:</b> Sebuah drone pengawas kualitas udara terbang sejauh 5 km ke arah timur, kemudian berbelok 90 derajat ke utara dan terbang sejauh 3 km.</p><ul>  <li>a. Nyatakan perpindahan drone dalam bentuk vektor komponen.</li>  <li>b. Jika drone tersebut kembali ke titik awal, berapa vektor perpindahan yang harus dilakukan?</li></ul><p><b>Masalah 3:</b> Diberikan vektor kecepatan angin v = (4, -2) m/s dan vektor arah penerbangan burung w = (1, 2) m/s.</p><ul>  <li>a. Hitunglah dot product dari v dan w.</li>  <li>b. Apa makna hasil dot product tersebut dalam kaitannya dengan sudut antara dua vektor?</li></ul>\", \"meeting_range\": \"1-1\"}]','Pertemuan ini membahas pengenalan konsep vektor, notasi, serta operasi aljabar dasar seperti penjumlahan, pengurangan, perkalian dengan skalar, dan pengantar dot product melalui pendekatan Problem Based Learning.',NULL,'2026-07-19 15:03:29','2026-07-19 15:04:01');
/*!40000 ALTER TABLE `ai_generated_modules` ENABLE KEYS */;
