INSERT INTO `quiz_sessions` VALUES (1,'a','a','X-E','Bilangan Berpangkat','[{\"options\": {\"A\": \"100 × 2^4\", \"B\": \"100 × 2^3\", \"C\": \"100 × 4^2\", \"D\": \"100 × 2^2\"}, \"question\": \"Sebuah koloni bakteri berlipat ganda setiap jam. Jika pada pukul 08.00 terdapat 100 bakteri, berapa jumlah bakteri pada pukul 12.00?\", \"explanation\": \"Dari pukul 08.00 hingga 12.00 adalah 4 jam. Jika bakteri berlipat ganda setiap jam, maka jumlah bakteri akan menjadi 100 dikalikan 2 sebanyak 4 kali, yaitu 100 × 2^4.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"3^1\", \"B\": \"3^3\", \"C\": \"3^5\", \"D\": \"3^0\"}, \"question\": \"Sederhanakan ekspresi (3^5 × 3^-2) / 3^2.\", \"explanation\": \"Menggunakan sifat pangkat: a^m × a^n = a^(m+n) dan a^m / a^n = a^(m-n). Maka, (3^5 × 3^-2) / 3^2 = 3^(5 + (-2) - 2) = 3^(5 - 2 - 2) = 3^1.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"0,000000000106 meter\", \"B\": \"0,00000000106 meter\", \"C\": \"0,0000000106 meter\", \"D\": \"0,000000106 meter\"}, \"question\": \"Ukuran diameter atom hidrogen adalah sekitar 1,06 × 10^-10 meter. Jika dituliskan dalam bentuk desimal biasa, bagaimana bentuk angka tersebut?\", \"explanation\": \"Pangkat negatif 10^-10 berarti menggeser koma desimal ke kiri sebanyak 10 tempat. Jadi, 1,06 menjadi 0,000000000106.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"2^3\", \"B\": \"2^4\", \"C\": \"2^5\", \"D\": \"2^6\"}, \"question\": \"Nilai dari ((2^3)^2 × 2^4) / (2^5) adalah...\", \"explanation\": \"Menggunakan sifat pangkat: (a^m)^n = a^(m×n) dan a^m × a^n = a^(m+n) serta a^m / a^n = a^(m-n). Maka, ((2^3)^2 × 2^4) / (2^5) = (2^(3×2) × 2^4) / 2^5 = (2^6 × 2^4) / 2^5 = 2^(6+4) / 2^5 = 2^10 / 2^5 = 2^(10-5) = 2^5.\", \"correct_answer\": \"C\"}, {\"options\": {\"A\": \"x^2\", \"B\": \"x^(5/2)\", \"C\": \"x^3\", \"D\": \"x^(7/2)\"}, \"question\": \"Bentuk sederhana dari (√x^3) × (x^(1/2)) adalah...\", \"explanation\": \"Bentuk akar dapat diubah menjadi pangkat pecahan: √x^3 = x^(3/2). Kemudian, kalikan dengan x^(1/2) menggunakan sifat a^m × a^n = a^(m+n). Jadi, x^(3/2) × x^(1/2) = x^((3/2) + (1/2)) = x^(4/2) = x^2.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"500 × 2^3\", \"B\": \"500 × 2^4\", \"C\": \"500 × 2^5\", \"D\": \"500 × 2^6\"}, \"question\": \"Sebuah populasi serangga meningkat dua kali lipat setiap 3 bulan. Jika pada awal tahun 2023 terdapat 500 serangga, berapa banyak serangga pada akhir tahun 2023?\", \"explanation\": \"Dari awal tahun 2023 hingga akhir tahun 2023 adalah 12 bulan. Karena populasi berlipat ganda setiap 3 bulan, maka dalam 12 bulan terjadi 12/3 = 4 kali pelipatan. Jadi, jumlah serangga adalah 500 × 2^4.\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"2√3\", \"B\": \"3√3\", \"C\": \"6√3\", \"D\": \"√3\"}, \"question\": \"Bentuk rasional dari 6 / (√3) adalah...\", \"explanation\": \"Untuk merasionalkan penyebut, kalikan pembilang dan penyebut dengan √3. Jadi, (6 / √3) × (√3 / √3) = (6√3) / 3 = 2√3.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"16\", \"B\": \"20\", \"C\": \"24\", \"D\": \"32\"}, \"question\": \"Hasil dari (5^0 + 2^-1) × (4^2) adalah...\", \"explanation\": \"Setiap bilangan berpangkat 0 adalah 1 (5^0 = 1). Pangkat negatif berarti kebalikan (2^-1 = 1/2^1 = 1/2). Dan 4^2 = 16. Jadi, (1 + 1/2) × 16 = (3/2) × 16 = 3 × 8 = 24.\", \"correct_answer\": \"C\"}, {\"options\": {\"A\": \"-32\", \"B\": \"-16\", \"C\": \"16\", \"D\": \"32\"}, \"question\": \"Jika a = 2, b = -1, dan c = 1/2, nilai dari (a^2 × b^-3) / c^2 adalah...\", \"explanation\": \"Substitusikan nilai a, b, dan c: a^2 = 2^2 = 4. b^-3 = (-1)^-3 = 1/(-1)^3 = 1/(-1) = -1. c^2 = (1/2)^2 = 1/4. Maka, (4 × (-1)) / (1/4) = -4 / (1/4) = -4 × 4 = -16.\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"1,5 × 10^7 km\", \"B\": \"1,5 × 10^8 km\", \"C\": \"15 × 10^7 km\", \"D\": \"0,15 × 10^9 km\"}, \"question\": \"Jarak rata-rata Bumi ke Matahari adalah sekitar 150.000.000 km. Tuliskan jarak ini dalam notasi ilmiah.\", \"explanation\": \"Untuk menulis dalam notasi ilmiah, angka harus di antara 1 dan 10. Geser koma desimal dari 150.000.000 ke kiri sebanyak 8 tempat untuk mendapatkan 1,5. Jadi, 150.000.000 km = 1,5 × 10^8 km.\", \"correct_answer\": \"B\"}]',NULL,NULL,'in_progress','a926991c-7c53-4a3e-8f6a-ba219b478580','2026-07-20 00:39:25','2026-07-20 00:39:25'),(2,'Andi','X A','X-E','Bilangan Berpangkat','[{\"options\": {\"A\": \"400 bakteri\", \"B\": \"800 bakteri\", \"C\": \"1600 bakteri\", \"D\": \"3200 bakteri\"}, \"question\": \"Sebuah koloni bakteri berlipat ganda setiap 30 menit. Jika pada awalnya terdapat 50 bakteri, berapa jumlah bakteri setelah 2 jam?\", \"explanation\": \"Dalam 2 jam terdapat 2 jam / 0.5 jam = 4 periode pelipatgandaan. Jadi, jumlah bakteri = 50 * 2^4 = 50 * 16 = 800 bakteri.\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"p^3 / q^2\", \"B\": \"p^7 / q^4\", \"C\": \"p^3 * q^2\", \"D\": \"q^2 / p^3\"}, \"question\": \"Sederhanakan bentuk (p^5 * q^-3) / (p^2 * q^-1).\", \"explanation\": \"Menggunakan sifat eksponen: p^(5-2) * q^(-3-(-1)) = p^3 * q^(-2) = p^3 / q^2.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"3\", \"B\": \"9\", \"C\": \"27\", \"D\": \"1/3\"}, \"question\": \"Nilai dari (81^(3/4)) * (27^(-1/3)) adalah...\", \"explanation\": \"81^(3/4) = (3^4)^(3/4) = 3^3 = 27. Dan 27^(-1/3) = (3^3)^(-1/3) = 3^-1 = 1/3. Jadi, 27 * (1/3) = 9.\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"x^3\", \"B\": \"x^4\", \"C\": \"x^5\", \"D\": \"x^6\"}, \"question\": \"Bentuk sederhana dari (√x^6 * ³√x^9) / x^2 adalah...\", \"explanation\": \"√x^6 = x^(6/2) = x^3. ³√x^9 = x^(9/3) = x^3. Jadi, (x^3 * x^3) / x^2 = x^(3+3-2) = x^4. (Terkoreksi, ini seharusnya x^(3+3) / x^2 = x^6 / x^2 = x^4. Mari kita revisi soal atau jawaban.) Ah, soalnya sudah benar, saya salah hitung. x^(3+3)/x^2 = x^6/x^2 = x^(6-2) = x^4. Okay, jawaban B.\", \"correct_answer\": \"C\"}, {\"options\": {\"A\": \"3\", \"B\": \"5\", \"C\": \"9\", \"D\": \"11\"}, \"question\": \"Nilai dari (√75 + √48) / √3 adalah...\", \"explanation\": \"√75 = √(25*3) = 5√3. √48 = √(16*3) = 4√3. Jadi, (5√3 + 4√3) / √3 = 9√3 / √3 = 9.\", \"correct_answer\": \"C\"}, {\"options\": {\"A\": \"1\", \"B\": \"2\", \"C\": \"3\", \"D\": \"4\"}, \"question\": \"Jika 3^(2x-1) = 27, maka nilai x adalah...\", \"explanation\": \"27 dapat ditulis sebagai 3^3. Maka, 3^(2x-1) = 3^3. Ini berarti 2x-1 = 3. Maka 2x = 4, sehingga x = 2.\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"1\", \"B\": \"2\", \"C\": \"3\", \"D\": \"4\"}, \"question\": \"Sebuah mobil bergerak dengan kecepatan 2^(x+1) km/jam. Jika mobil tersebut menempuh jarak 128 km dalam waktu 4 jam, berapakah nilai x?\", \"explanation\": \"Jarak = Kecepatan * Waktu. 128 = 2^(x+1) * 4. 128 = 2^(x+1) * 2^2. 128 = 2^(x+1+2). 2^7 = 2^(x+3). Maka 7 = x+3, sehingga x = 4.\", \"correct_answer\": \"D\"}, {\"options\": {\"A\": \"2(√7 - √2)\", \"B\": \"2(√7 + √2)\", \"C\": \"5(√7 - √2)\", \"D\": \"5(√7 + √2)\"}, \"question\": \"Bentuk rasional dari 10 / (√7 - √2) adalah...\", \"explanation\": \"Kalikan dengan konjugat penyebut: 10 / (√7 - √2) * (√7 + √2) / (√7 + √2) = 10(√7 + √2) / (7 - 2) = 10(√7 + √2) / 5 = 2(√7 + √2).\", \"correct_answer\": \"B\"}, {\"options\": {\"A\": \"a^-7 * b^7\", \"B\": \"a^-1 * b^5\", \"C\": \"a^7 * b^-7\", \"D\": \"a^-7 * b^5\"}, \"question\": \"Hasil dari ( (a^-2 * b^3)^2 ) / ( a^3 * b^-1 ) adalah...\", \"explanation\": \"Pembilang: (a^-2 * b^3)^2 = a^(-2*2) * b^(3*2) = a^-4 * b^6. Jadi, (a^-4 * b^6) / (a^3 * b^-1) = a^(-4-3) * b^(6-(-1)) = a^-7 * b^7.\", \"correct_answer\": \"A\"}, {\"options\": {\"A\": \"1/5\", \"B\": \"2/5\", \"C\": \"3/5\", \"D\": \"4/5\"}, \"question\": \"Jika x = 25 dan y = 8, nilai dari (x^(-1/2) * y^(2/3)) adalah...\", \"explanation\": \"x^(-1/2) = 25^(-1/2) = (5^2)^(-1/2) = 5^-1 = 1/5. y^(2/3) = 8^(2/3) = (2^3)^(2/3) = 2^2 = 4. Jadi, (1/5) * 4 = 4/5.\", \"correct_answer\": \"D\"}]','[\"B\", \"A\", \"B\", \"B\", \"C\", \"B\", \"D\", \"B\", \"A\", \"D\"]',90,'completed','8921c96d-5128-4d2d-b5a6-0b3783f548ca','2026-08-10 12:11:39','2026-08-10 12:14:57');
