INSERT INTO `toolkits` VALUES (1,'kalkulator Grafik','calculate','url','https://www.desmos.com/calculator?lang=id',NULL,'2026-07-29 13:14:49','2026-07-29 13:14:49'),(2,'grafik','graph','code',NULL,'<!DOCTYPE html>\r\n<html lang=\"id\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\r\n<title>Kalkulator Grafik Interaktif</title>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mathjs/11.11.1/math.min.js\"></script>\r\n<style>\r\n  :root{\r\n    /* ===== Instrument / graph-paper theme (light) ===== */\r\n    --bg: #eef1f6;\r\n    --paper: #f7f9fc;\r\n    --grid-minor: #c9d3e0;\r\n    --grid-major: #93a4bd;\r\n    --axis: #223047;\r\n    --ink: #16202e;\r\n    --ink-soft: #51617a;\r\n    --panel: #ffffff;\r\n    --panel-border: #d7dfeb;\r\n    --accent: #e0641f;      /* amber pen */\r\n    --accent-2: #0f8b8d;    /* teal */\r\n    --accent-soft: rgba(224,100,31,0.14);\r\n    --danger: #d1495b;\r\n    --mono: \'SFMono-Regular\', Consolas, \'Liberation Mono\', Menlo, monospace;\r\n    --sans: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\r\n    --radius: 10px;\r\n    --shadow: 0 2px 10px rgba(20,30,50,0.08);\r\n  }\r\n  [data-theme=\"dark\"]{\r\n    --bg: #0d1420;\r\n    --paper: #0b0f18;\r\n    --grid-minor: #1c2735;\r\n    --grid-major: #2c3d52;\r\n    --axis: #8fa8c9;\r\n    --ink: #e7edf5;\r\n    --ink-soft: #93a4bd;\r\n    --panel: #101825;\r\n    --panel-border: #223047;\r\n    --accent: #ffb454;\r\n    --accent-2: #37e6c9;\r\n    --accent-soft: rgba(255,180,84,0.14);\r\n    --danger: #ff7a8a;\r\n    --shadow: 0 2px 16px rgba(0,0,0,0.5);\r\n  }\r\n  *{box-sizing:border-box;}\r\n  html,body{height:100%;}\r\n  body{\r\n    margin:0; font-family:var(--sans); background:var(--bg); color:var(--ink);\r\n    display:flex; flex-direction:column; height:100vh; overflow:hidden;\r\n  }\r\n  button{font-family:inherit;}\r\n  input{font-family:inherit;}\r\n\r\n  /* ===== Top bar ===== */\r\n  #topbar{\r\n    display:flex; align-items:center; gap:6px; padding:8px 10px;\r\n    background:var(--panel); border-bottom:1px solid var(--panel-border);\r\n    flex-wrap:wrap; z-index:20;\r\n  }\r\n  .brand{\r\n    font-family:var(--mono); font-weight:700; letter-spacing:0.5px; font-size:13px;\r\n    color:var(--ink); margin-right:8px; white-space:nowrap; display:flex; align-items:center; gap:6px;\r\n  }\r\n  .brand .dot{width:9px;height:9px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);}\r\n  .tbtn{\r\n    display:flex; align-items:center; gap:5px; padding:6px 10px; border-radius:8px;\r\n    border:1px solid var(--panel-border); background:var(--paper); color:var(--ink);\r\n    font-size:12.5px; cursor:pointer; transition:.12s; white-space:nowrap;\r\n  }\r\n  .tbtn:hover{ border-color:var(--accent); color:var(--accent); }\r\n  .tbtn.active{ background:var(--accent-soft); border-color:var(--accent); color:var(--accent); }\r\n  .tbtn svg{width:14px;height:14px;}\r\n  #sidebarToggle{display:none;}\r\n  .spacer{flex:1;}\r\n\r\n  /* ===== Layout ===== */\r\n  #app{ flex:1; display:flex; min-height:0; position:relative; }\r\n  #sidebar{\r\n    width:340px; min-width:340px; background:var(--panel); border-right:1px solid var(--panel-border);\r\n    overflow-y:auto; padding:12px; display:flex; flex-direction:column; gap:14px;\r\n  }\r\n  #main{ flex:1; position:relative; display:flex; flex-direction:column; min-width:0; }\r\n  #canvasWrap{ flex:1; position:relative; overflow:hidden; background:var(--paper); }\r\n  canvas{ display:block; touch-action:none; cursor:grab; }\r\n  canvas.dragging{ cursor:grabbing; }\r\n\r\n  .section{ border:1px solid var(--panel-border); border-radius:var(--radius); padding:10px; background:var(--paper); }\r\n  .section h3{\r\n    margin:0 0 8px 0; font-size:11px; text-transform:uppercase; letter-spacing:1px;\r\n    color:var(--ink-soft); font-family:var(--mono); display:flex; align-items:center; justify-content:space-between;\r\n  }\r\n\r\n  /* ===== Function rows ===== */\r\n  .fnrow{\r\n    display:flex; align-items:center; gap:6px; padding:6px; border-radius:8px; margin-bottom:6px;\r\n    background:var(--panel); border:1px solid var(--panel-border);\r\n  }\r\n  .fnrow.active{ border-color:var(--accent); box-shadow:0 0 0 2px var(--accent-soft); }\r\n  .swatch{ width:14px;height:14px;border-radius:4px;flex:none; cursor:pointer; border:1px solid rgba(0,0,0,0.15);}\r\n  .fnrow input[type=text]{\r\n    flex:1; min-width:0; border:none; background:transparent; color:var(--ink);\r\n    font-family:var(--mono); font-size:13px; padding:4px 2px; outline:none;\r\n  }\r\n  .fnlabel{ font-family:var(--mono); font-size:11px; color:var(--ink-soft); min-width:16px; }\r\n  .iconbtn{\r\n    border:none; background:transparent; color:var(--ink-soft); cursor:pointer; padding:3px;\r\n    border-radius:5px; display:flex; align-items:center; justify-content:center;\r\n  }\r\n  .iconbtn:hover{ color:var(--accent); background:var(--accent-soft); }\r\n  .iconbtn svg{width:15px;height:15px;}\r\n  .fnpretty{ font-size:11px; color:var(--ink-soft); padding:0 4px 4px 26px; font-family:var(--mono); }\r\n  .fndomain{ display:flex; gap:4px; padding:0 4px 6px 26px; }\r\n  .fndomain input{\r\n    width:56px; font-size:11px; font-family:var(--mono); background:var(--paper);\r\n    border:1px solid var(--panel-border); border-radius:5px; padding:3px 4px; color:var(--ink);\r\n  }\r\n  .addfn{\r\n    width:100%; padding:8px; border-radius:8px; border:1.5px dashed var(--panel-border);\r\n    background:transparent; color:var(--accent); font-weight:600; cursor:pointer; font-size:13px;\r\n  }\r\n  .addfn:hover{ border-color:var(--accent); background:var(--accent-soft); }\r\n\r\n  /* ===== small controls ===== */\r\n  .row{ display:flex; align-items:center; gap:8px; margin-bottom:6px; font-size:12.5px; }\r\n  .row label{ flex:1; color:var(--ink-soft); display:flex; align-items:center; gap:6px; }\r\n  .row input[type=number]{\r\n    width:70px; font-family:var(--mono); font-size:12px; background:var(--paper);\r\n    border:1px solid var(--panel-border); border-radius:6px; padding:4px 6px; color:var(--ink);\r\n  }\r\n  select{\r\n    font-family:var(--mono); font-size:12px; background:var(--paper); color:var(--ink);\r\n    border:1px solid var(--panel-border); border-radius:6px; padding:4px 6px; width:100%;\r\n  }\r\n  .checkgrid{ display:grid; grid-template-columns:1fr 1fr; gap:4px 8px; }\r\n  .checkgrid label{ display:flex; align-items:center; gap:6px; font-size:12.5px; color:var(--ink-soft); }\r\n  input[type=checkbox]{ accent-color:var(--accent); width:14px;height:14px; }\r\n  input[type=range]{ width:100%; accent-color:var(--accent); }\r\n\r\n  .btnrow{ display:flex; gap:6px; flex-wrap:wrap; }\r\n  .miniBtn{\r\n    flex:1; min-width:70px; padding:6px 8px; font-size:11.5px; border-radius:7px;\r\n    border:1px solid var(--panel-border); background:var(--panel); color:var(--ink); cursor:pointer;\r\n  }\r\n  .miniBtn:hover{ border-color:var(--accent-2); color:var(--accent-2); }\r\n\r\n  .paramrow{ display:flex; align-items:center; gap:8px; margin-bottom:8px; }\r\n  .paramname{ font-family:var(--mono); font-weight:700; width:16px; color:var(--accent-2); font-size:13px;}\r\n  .paramval{ font-family:var(--mono); font-size:11.5px; color:var(--ink-soft); width:44px; text-align:right;}\r\n\r\n  .libbtn{\r\n    font-size:11px; font-family:var(--mono); padding:5px 7px; border-radius:6px; margin:2px;\r\n    border:1px solid var(--panel-border); background:var(--panel); color:var(--ink); cursor:pointer;\r\n  }\r\n  .libbtn:hover{ border-color:var(--accent); color:var(--accent); }\r\n  .libgroup{ margin-bottom:6px; }\r\n  .libgroup .glabel{ font-size:10.5px; color:var(--ink-soft); font-family:var(--mono); margin-bottom:3px; text-transform:uppercase; letter-spacing:.5px;}\r\n\r\n  #resultsLog{ max-height:150px; overflow-y:auto; font-family:var(--mono); font-size:11.5px; }\r\n  .logitem{ padding:4px 6px; border-radius:6px; margin-bottom:4px; background:var(--panel); border:1px solid var(--panel-border); display:flex; justify-content:space-between; gap:6px;}\r\n  .logitem .swatch2{ width:8px;height:8px;border-radius:50%;flex:none; margin-top:3px;}\r\n\r\n  /* ===== HUD / crosshair readout ===== */\r\n  #hud{\r\n    position:absolute; top:10px; left:10px; background:var(--panel); border:1px solid var(--panel-border);\r\n    border-radius:8px; padding:8px 10px; font-family:var(--mono); font-size:11.5px; box-shadow:var(--shadow);\r\n    pointer-events:none; min-width:150px; display:none;\r\n  }\r\n  #hud .hx{ color:var(--accent); font-weight:700; }\r\n  #hud .hy{ color:var(--accent-2); font-weight:700; }\r\n  #hud .hrow{ display:flex; justify-content:space-between; gap:10px; }\r\n\r\n  #zoomHud{\r\n    position:absolute; bottom:10px; right:10px; background:var(--panel); border:1px solid var(--panel-border);\r\n    border-radius:8px; padding:5px 9px; font-family:var(--mono); font-size:11px; color:var(--ink-soft);\r\n    box-shadow:var(--shadow); pointer-events:none;\r\n  }\r\n\r\n  #toast{\r\n    position:absolute; bottom:16px; left:50%; transform:translateX(-50%) translateY(10px);\r\n    background:var(--ink); color:var(--paper); padding:8px 16px; border-radius:20px; font-size:12.5px;\r\n    opacity:0; transition:.25s; pointer-events:none; z-index:50; font-family:var(--sans);\r\n  }\r\n  #toast.show{ opacity:1; transform:translateX(-50%) translateY(0); }\r\n\r\n  ::-webkit-scrollbar{ width:8px; height:8px; }\r\n  ::-webkit-scrollbar-thumb{ background:var(--panel-border); border-radius:4px; }\r\n\r\n  /* ===== Responsive ===== */\r\n  @media (max-width: 860px){\r\n    #sidebar{\r\n      position:absolute; left:0; top:0; bottom:0; z-index:30; transform:translateX(-105%);\r\n      transition:transform .2s ease; box-shadow:0 0 30px rgba(0,0,0,0.25); width:88vw; min-width:0;\r\n    }\r\n    #sidebar.open{ transform:translateX(0); }\r\n    #sidebarToggle{ display:flex; }\r\n    .brand span.full{ display:none; }\r\n    #topbar{ gap:4px; }\r\n    .tbtn span.label{ display:none; }\r\n    .tbtn{ padding:7px; }\r\n    #hud{ font-size:10.5px; padding:6px 8px; }\r\n  }\r\n  @media (max-width:860px){\r\n    .tbtn.essential span.label{ display:inline; }\r\n  }\r\n</style>\r\n</head>\r\n<body data-theme=\"light\">\r\n\r\n<div id=\"topbar\">\r\n  <button class=\"tbtn\" id=\"sidebarToggle\" title=\"Menu\">\r\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\r\n  </button>\r\n  <div class=\"brand\"><span class=\"dot\"></span>ƒ<span class=\"full\">(x) · Kalkulator Grafik</span></div>\r\n\r\n  <button class=\"tbtn essential\" id=\"btnGrid\" title=\"Tampilkan/Sembunyikan Kisi\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg><span class=\"label\">Grid</span></button>\r\n  <button class=\"tbtn essential\" id=\"btnReset\" title=\"Atur Ulang Tampilan\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M1 4v6h6M23 20v-6h-6\"/><path d=\"M20.49 9A9 9 0 0 0 5.6 5.6L1 10m22 4l-4.6 4.4A9 9 0 0 1 3.51 15\"/></svg><span class=\"label\">Reset</span></button>\r\n  <button class=\"tbtn\" id=\"btnZoomIn\" title=\"Perbesar\">+</button>\r\n  <button class=\"tbtn\" id=\"btnZoomOut\" title=\"Perkecil\">–</button>\r\n  <button class=\"tbtn essential\" id=\"btnCenter\" title=\"Pusatkan ke Origin\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"2\"/><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4\"/></svg><span class=\"label\">Center</span></button>\r\n  <button class=\"tbtn\" id=\"btnDeriv\" title=\"Turunan fungsi aktif\">f\'<span class=\"label\">Turunan</span></button>\r\n  <button class=\"tbtn\" id=\"btnIntegral\" title=\"Integral (luas) fungsi aktif\">∫<span class=\"label\">Integral</span></button>\r\n  <button class=\"tbtn\" id=\"btnRoots\" title=\"Cari akar fungsi aktif\">0<span class=\"label\">Akar</span></button>\r\n  <button class=\"tbtn\" id=\"btnExtrema\" title=\"Cari ekstrem fungsi aktif\">↕<span class=\"label\">Ekstrem</span></button>\r\n  <div class=\"spacer\"></div>\r\n  <button class=\"tbtn essential\" id=\"btnSave\" title=\"Simpan sebagai gambar\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3\"/></svg><span class=\"label\">Save</span></button>\r\n  <button class=\"tbtn essential\" id=\"btnShare\" title=\"Bagikan tautan\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"18\" cy=\"5\" r=\"3\"/><circle cx=\"6\" cy=\"12\" r=\"3\"/><circle cx=\"18\" cy=\"19\" r=\"3\"/><path d=\"M8.6 13.5l6.8 3.9M15.4 6.5L8.6 10.4\"/></svg><span class=\"label\">Share</span></button>\r\n  <button class=\"tbtn essential\" id=\"btnDark\" title=\"Mode Gelap\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8z\"/></svg><span class=\"label\">Dark</span></button>\r\n</div>\r\n\r\n<div id=\"app\">\r\n  <div id=\"sidebar\">\r\n\r\n    <div class=\"section\">\r\n      <h3>Fungsi <span id=\"fnCount\" style=\"font-weight:400;\">0 aktif</span></h3>\r\n      <div id=\"fnList\"></div>\r\n      <button class=\"addfn\" id=\"addFn\">+ Tambah Fungsi</button>\r\n    </div>\r\n\r\n    <div class=\"section\" id=\"paramsSection\" style=\"display:none;\">\r\n      <h3>Slider Parameter</h3>\r\n      <div id=\"paramList\"></div>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n      <h3>Pustaka Fungsi</h3>\r\n      <div class=\"libgroup\"><div class=\"glabel\">Aljabar</div><div class=\"btnrow\" id=\"libAljabar\"></div></div>\r\n      <div class=\"libgroup\"><div class=\"glabel\">Trigonometri</div><div class=\"btnrow\" id=\"libTrig\"></div></div>\r\n      <div class=\"libgroup\"><div class=\"glabel\">Logaritma &amp; Eksponen</div><div class=\"btnrow\" id=\"libLog\"></div></div>\r\n      <div class=\"libgroup\"><div class=\"glabel\">Piecewise</div><div class=\"btnrow\" id=\"libPiece\"></div></div>\r\n      <div class=\"row\" style=\"margin-top:6px;\">\r\n        <label>Mode sudut trig</label>\r\n        <select id=\"angleMode\" style=\"width:110px;\"><option value=\"rad\">Radian</option><option value=\"deg\">Derajat</option></select>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n      <h3>Domain Tampilan (global)</h3>\r\n      <div class=\"row\">\r\n        <label>x min</label><input type=\"number\" id=\"domMin\" value=\"-20\" step=\"1\">\r\n        <label>x max</label><input type=\"number\" id=\"domMax\" value=\"20\" step=\"1\">\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n      <h3>Kisi-kisi &amp; Tampilan</h3>\r\n      <div class=\"checkgrid\">\r\n        <label><input type=\"checkbox\" id=\"chkGrid\" checked> Kisi-kisi</label>\r\n        <label><input type=\"checkbox\" id=\"chkAxes\" checked> Sumbu</label>\r\n        <label><input type=\"checkbox\" id=\"chkLabels\" checked> Label</label>\r\n        <label><input type=\"checkbox\" id=\"chkTicks\" checked> Centang</label>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n      <h3>Analisis</h3>\r\n      <div class=\"row\"><label>Fungsi A</label></div>\r\n      <select id=\"fnA\" style=\"margin-bottom:6px;\"></select>\r\n      <div class=\"row\"><label>Fungsi B (interseksi)</label></div>\r\n      <select id=\"fnB\" style=\"margin-bottom:8px;\"></select>\r\n      <div class=\"btnrow\" style=\"margin-bottom:8px;\">\r\n        <button class=\"miniBtn\" id=\"actRoots\">Akar (sb-X)</button>\r\n        <button class=\"miniBtn\" id=\"actExtrema\">Maks/Min</button>\r\n        <button class=\"miniBtn\" id=\"actIntersect\">Interseksi A∩B</button>\r\n        <button class=\"miniBtn\" id=\"actAsymp\">Asimtot</button>\r\n        <button class=\"miniBtn\" id=\"actDeriv\">Turunan → plot</button>\r\n      </div>\r\n      <div class=\"row\" style=\"gap:4px;\">\r\n        <label style=\"flex:none;\">∫ dari</label><input type=\"number\" id=\"intA\" value=\"0\" style=\"width:56px;\">\r\n        <label style=\"flex:none;\">ke</label><input type=\"number\" id=\"intB\" value=\"2\" style=\"width:56px;\">\r\n        <button class=\"miniBtn\" id=\"actIntegral\" style=\"flex:1;\">Arsir Luas</button>\r\n      </div>\r\n      <div id=\"resultsLog\" style=\"margin-top:8px;\"></div>\r\n      <button class=\"miniBtn\" id=\"clearMarkers\" style=\"width:100%; margin-top:6px;\">Bersihkan Penanda</button>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n      <h3>Contoh &amp; Tabel Nilai</h3>\r\n      <div class=\"btnrow\" style=\"margin-bottom:8px;\">\r\n        <button class=\"miniBtn\" id=\"loadDemo\">Muat Contoh</button>\r\n        <button class=\"miniBtn\" id=\"exportTable\">Ekspor Tabel (CSV)</button>\r\n      </div>\r\n      <div style=\"font-size:11px; color:var(--ink-soft); font-family:var(--mono); line-height:1.5;\">\r\n        Pintasan: roda mouse = zoom · seret = geser · +/- = zoom · d = mode gelap · r = reset\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n\r\n  <div id=\"main\">\r\n    <div id=\"canvasWrap\">\r\n      <canvas id=\"graph\"></canvas>\r\n      <div id=\"hud\"></div>\r\n      <div id=\"zoomHud\">skala: 40 px/unit</div>\r\n      <div id=\"toast\"></div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n(function(){\r\n\"use strict\";\r\n\r\n/* ======================================================================\r\n   STATE\r\n====================================================================== */\r\nconst palette = [\'#e0641f\',\'#0f8b8d\',\'#5b6ee1\',\'#c0367e\',\'#3f9142\',\'#b3892b\',\'#7b4fb3\',\'#2a7fc9\',\'#c14646\',\'#3aa17e\'];\r\nlet colorIdx = 0;\r\n\r\nconst state = {\r\n  functions: [],\r\n  params: {},        // name -> value\r\n  paramCfg: {},       // name -> {min,max,step}\r\n  view: { scale: 40, ox: 0, oy: 0 },\r\n  grid: { lines:true, axes:true, labels:true, ticks:true },\r\n  dark: false,\r\n  angleMode: \'rad\',\r\n  activeId: null,\r\n  domain: { min:-20, max:20 },\r\n  markers: [],        // {x,y,label,color,type}\r\n  integralShade: null // {fnId,a,b,color,value}\r\n};\r\n\r\nlet uid = 1;\r\nfunction nextId(){ return \'f\' + (uid++); }\r\n\r\n/* ======================================================================\r\n   DOM refs\r\n====================================================================== */\r\nconst canvas = document.getElementById(\'graph\');\r\nconst ctx = canvas.getContext(\'2d\');\r\nconst canvasWrap = document.getElementById(\'canvasWrap\');\r\nconst hud = document.getElementById(\'hud\');\r\nconst zoomHud = document.getElementById(\'zoomHud\');\r\nconst toastEl = document.getElementById(\'toast\');\r\nconst fnList = document.getElementById(\'fnList\');\r\nconst fnCount = document.getElementById(\'fnCount\');\r\nconst paramsSection = document.getElementById(\'paramsSection\');\r\nconst paramList = document.getElementById(\'paramList\');\r\nconst resultsLog = document.getElementById(\'resultsLog\');\r\nconst fnASel = document.getElementById(\'fnA\');\r\nconst fnBSel = document.getElementById(\'fnB\');\r\n\r\n/* ======================================================================\r\n   Utility: toast\r\n====================================================================== */\r\nlet toastTimer=null;\r\nfunction toast(msg){\r\n  toastEl.textContent = msg;\r\n  toastEl.classList.add(\'show\');\r\n  clearTimeout(toastTimer);\r\n  toastTimer = setTimeout(()=> toastEl.classList.remove(\'show\'), 2200);\r\n}\r\n\r\n/* ======================================================================\r\n   Pretty-print: penguraian otomatis  (x^2 -> x², sqrt(x)->√x, pi->π)\r\n====================================================================== */\r\nconst supMap = {\r\n  \'0\':\'⁰\',\'1\':\'¹\',\'2\':\'²\',\'3\':\'³\',\'4\':\'⁴\',\'5\':\'⁵\',\'6\':\'⁶\',\'7\':\'⁷\',\'8\':\'⁸\',\'9\':\'⁹\',\r\n  \'+\':\'⁺\',\'-\':\'⁻\',\'(\':\'⁽\',\')\':\'⁾\',\'.\':\'·\',\r\n  \'a\':\'ᵃ\',\'b\':\'ᵇ\',\'c\':\'ᶜ\',\'d\':\'ᵈ\',\'e\':\'ᵉ\',\'f\':\'ᶠ\',\'g\':\'ᵍ\',\'h\':\'ʰ\',\'i\':\'ⁱ\',\'j\':\'ʲ\',\r\n  \'k\':\'ᵏ\',\'l\':\'ˡ\',\'m\':\'ᵐ\',\'n\':\'ⁿ\',\'o\':\'ᵒ\',\'p\':\'ᵖ\',\'r\':\'ʳ\',\'s\':\'ˢ\',\'t\':\'ᵗ\',\'u\':\'ᵘ\',\r\n  \'v\':\'ᵛ\',\'w\':\'ʷ\',\'x\':\'ˣ\',\'y\':\'ʸ\',\'z\':\'ᶻ\'\r\n};\r\nfunction toSuper(s){\r\n  return s.split(\'\').map(c => supMap[c] !== undefined ? supMap[c] : c).join(\'\');\r\n}\r\nfunction prettify(raw){\r\n  if(!raw) return \'\';\r\n  let out = raw;\r\n  out = out.replace(/\\bsqrt\\(/g, \'√(\');\r\n  out = out.replace(/\\bpi\\b/g, \'π\');\r\n  out = out.replace(/\\*/g, \'·\');\r\n  // exponent: ^( group ) or ^token\r\n  out = out.replace(/\\^(\\(([^()]*)\\)|[A-Za-z0-9]+)/g, (m, g1, g2) => {\r\n    const inner = g2 !== undefined ? g2 : g1;\r\n    return toSuper(inner);\r\n  });\r\n  return out;\r\n}\r\n\r\n/* ======================================================================\r\n   Preprocess expr for math.js parsing\r\n====================================================================== */\r\nfunction preprocess(raw){\r\n  let s = raw.trim();\r\n  if(!s) return \'0\';\r\n  s = s.replace(/√\\(/g, \'sqrt(\');\r\n  s = s.replace(/π/g, \'pi\');\r\n  s = s.replace(/·/g, \'*\');\r\n  s = s.replace(/\\bln\\(/g, \'log(\');\r\n  return s;\r\n}\r\n\r\n/* ======================================================================\r\n   Detect free parameters in an expression (letters that aren\'t x / known consts)\r\n====================================================================== */\r\nconst RESERVED = new Set([\'x\',\'e\',\'pi\',\'i\',\'true\',\'false\',\'Infinity\',\'NaN\']);\r\nconst FN_NAMES = new Set([\'sin\',\'cos\',\'tan\',\'asin\',\'acos\',\'atan\',\'atan2\',\'sinh\',\'cosh\',\'tanh\',\r\n  \'sqrt\',\'log\',\'log10\',\'log2\',\'exp\',\'abs\',\'floor\',\'ceil\',\'round\',\'sign\',\'pow\',\'min\',\'max\',\'mod\',\'cbrt\']);\r\n\r\nfunction detectParams(node){\r\n  const found = new Set();\r\n  try{\r\n    node.traverse(n => {\r\n      if(n.isSymbolNode && !RESERVED.has(n.name) && !FN_NAMES.has(n.name) && n.name.length<=2){\r\n        found.add(n.name);\r\n      }\r\n    });\r\n  }catch(e){}\r\n  return Array.from(found);\r\n}\r\n\r\n/* ======================================================================\r\n   Function object management\r\n====================================================================== */\r\nfunction makeFn(rawExpr, opts={}){\r\n  const f = {\r\n    id: nextId(),\r\n    raw: rawExpr,\r\n    color: opts.color || palette[colorIdx++ % palette.length],\r\n    visible: true,\r\n    domainMin: opts.domainMin ?? null,\r\n    domainMax: opts.domainMax ?? null,\r\n    isDerivative: !!opts.isDerivative,\r\n    node: null, compiled: null, params: [], error: null\r\n  };\r\n  compileFn(f);\r\n  return f;\r\n}\r\n\r\nfunction compileFn(f){\r\n  f.error = null;\r\n  try{\r\n    const processed = preprocess(f.raw);\r\n    const node = math.parse(processed);\r\n    f.node = node;\r\n    f.compiled = node.compile();\r\n    f.params = detectParams(node);\r\n    ensureParams(f.params);\r\n  }catch(e){\r\n    f.node = null; f.compiled = null; f.error = \'sintaks tidak valid\';\r\n  }\r\n}\r\n\r\nfunction ensureParams(names){\r\n  let changed = false;\r\n  names.forEach(n=>{\r\n    if(!(n in state.params)){\r\n      state.params[n] = 1;\r\n      state.paramCfg[n] = {min:-10, max:10, step:0.1};\r\n      changed = true;\r\n    }\r\n  });\r\n  if(changed) renderParams();\r\n}\r\n\r\nfunction evalScope(x){\r\n  const scope = Object.assign({}, state.params, {x});\r\n  if(state.angleMode === \'deg\'){\r\n    scope.sin = v => Math.sin(v*Math.PI/180);\r\n    scope.cos = v => Math.cos(v*Math.PI/180);\r\n    scope.tan = v => Math.tan(v*Math.PI/180);\r\n    scope.asin = v => Math.asin(v)*180/Math.PI;\r\n    scope.acos = v => Math.acos(v)*180/Math.PI;\r\n    scope.atan = v => Math.atan(v)*180/Math.PI;\r\n  }\r\n  return scope;\r\n}\r\n\r\nfunction evalFn(f, x){\r\n  if(!f.compiled) return NaN;\r\n  if(f.domainMin!=null && x < f.domainMin) return NaN;\r\n  if(f.domainMax!=null && x > f.domainMax) return NaN;\r\n  try{\r\n    const v = f.compiled.evaluate(evalScope(x));\r\n    if(typeof v !== \'number\' || !isFinite(v)) return NaN;\r\n    return v;\r\n  }catch(e){ return NaN; }\r\n}\r\n\r\n/* ======================================================================\r\n   Coordinate transforms\r\n====================================================================== */\r\nlet dpr = Math.max(1, window.devicePixelRatio || 1);\r\nfunction cssW(){ return canvasWrap.clientWidth; }\r\nfunction cssH(){ return canvasWrap.clientHeight; }\r\n\r\nfunction worldToScreen(x,y){\r\n  const cx = cssW()/2, cy = cssH()/2;\r\n  return [ cx + (x - state.view.ox)*state.view.scale, cy - (y - state.view.oy)*state.view.scale ];\r\n}\r\nfunction screenToWorld(px,py){\r\n  const cx = cssW()/2, cy = cssH()/2;\r\n  return [ state.view.ox + (px-cx)/state.view.scale, state.view.oy - (py-cy)/state.view.scale ];\r\n}\r\n\r\n/* ======================================================================\r\n   Nice-number step for grid spacing\r\n====================================================================== */\r\nfunction niceStep(targetPx){\r\n  const rawUnit = targetPx / state.view.scale;\r\n  const mag = Math.pow(10, Math.floor(Math.log10(rawUnit)));\r\n  const norm = rawUnit / mag;\r\n  let step;\r\n  if(norm < 1.5) step = 1;\r\n  else if(norm < 3.5) step = 2;\r\n  else if(norm < 7.5) step = 5;\r\n  else step = 10;\r\n  return step * mag;\r\n}\r\n\r\n/* ======================================================================\r\n   Resize canvas\r\n====================================================================== */\r\nfunction resizeCanvas(){\r\n  dpr = Math.max(1, window.devicePixelRatio || 1);\r\n  const w = cssW(), h = cssH();\r\n  canvas.width = Math.round(w*dpr);\r\n  canvas.height = Math.round(h*dpr);\r\n  canvas.style.width = w+\'px\';\r\n  canvas.style.height = h+\'px\';\r\n  ctx.setTransform(dpr,0,0,dpr,0,0);\r\n  render();\r\n}\r\nwindow.addEventListener(\'resize\', resizeCanvas);\r\n\r\n/* ======================================================================\r\n   Rendering\r\n====================================================================== */\r\nfunction cssVar(name){\r\n  return getComputedStyle(document.body).getPropertyValue(name).trim();\r\n}\r\n\r\nfunction render(){\r\n  const W = cssW(), H = cssH();\r\n  ctx.clearRect(0,0,W,H);\r\n  ctx.fillStyle = cssVar(\'--paper\');\r\n  ctx.fillRect(0,0,W,H);\r\n\r\n  if(state.grid.lines) drawGrid(W,H);\r\n  if(state.grid.axes) drawAxes(W,H);\r\n\r\n  drawDomainBounds(W,H);\r\n  drawIntegralShade(W,H);\r\n  state.functions.forEach(f=>{ if(f.visible) drawFunction(f,W,H); });\r\n  drawMarkers(W,H);\r\n  if(state.crosshairX !== undefined) drawCrosshair(W,H);\r\n\r\n  zoomHud.textContent = \'skala: \' + state.view.scale.toFixed(1) + \' px/unit\';\r\n}\r\n\r\nfunction drawGrid(W,H){\r\n  const step = niceStep(60);\r\n  const minorStep = step/5;\r\n  const [x0] = screenToWorld(0,0);\r\n  const [x1] = screenToWorld(W,0);\r\n  const [,y0] = screenToWorld(0,0);\r\n  const [,y1] = screenToWorld(0,H);\r\n\r\n  ctx.lineWidth = 1;\r\n  // minor grid\r\n  ctx.strokeStyle = cssVar(\'--grid-minor\');\r\n  ctx.beginPath();\r\n  let startX = Math.floor(x0/minorStep)*minorStep;\r\n  for(let x=startX; x<=x1; x+=minorStep){\r\n    const [sx] = worldToScreen(x,0);\r\n    ctx.moveTo(sx+0.5,0); ctx.lineTo(sx+0.5,H);\r\n  }\r\n  let startY = Math.floor(y1/minorStep)*minorStep;\r\n  for(let y=startY; y<=y0; y+=minorStep){\r\n    const [,sy] = worldToScreen(0,y);\r\n    ctx.moveTo(0,sy+0.5); ctx.lineTo(W,sy+0.5);\r\n  }\r\n  ctx.stroke();\r\n\r\n  // major grid\r\n  ctx.strokeStyle = cssVar(\'--grid-major\');\r\n  ctx.beginPath();\r\n  let sx0 = Math.floor(x0/step)*step;\r\n  for(let x=sx0; x<=x1; x+=step){\r\n    const [sx] = worldToScreen(x,0);\r\n    ctx.moveTo(sx+0.5,0); ctx.lineTo(sx+0.5,H);\r\n  }\r\n  let sy0 = Math.floor(y1/step)*step;\r\n  for(let y=sy0; y<=y0; y+=step){\r\n    const [,sy] = worldToScreen(0,y);\r\n    ctx.moveTo(0,sy+0.5); ctx.lineTo(W,sy+0.5);\r\n  }\r\n  ctx.stroke();\r\n\r\n  if(state.grid.labels || state.grid.ticks){\r\n    ctx.font = \'11px \' + cssVar(\'--mono\') || \'monospace\';\r\n    ctx.fillStyle = cssVar(\'--ink-soft\');\r\n    const [,zeroY] = worldToScreen(0,0);\r\n    const [zeroX] = worldToScreen(0,0);\r\n    const axisY = Math.min(Math.max(zeroY, 14), H-6);\r\n    const axisX = Math.min(Math.max(zeroX, 4), W-30);\r\n\r\n    for(let x=sx0; x<=x1; x+=step){\r\n      if(Math.abs(x) < step/1000) continue;\r\n      const [sx] = worldToScreen(x,0);\r\n      if(state.grid.ticks){\r\n        ctx.strokeStyle = cssVar(\'--axis\');\r\n        ctx.beginPath(); ctx.moveTo(sx+0.5, axisY-4); ctx.lineTo(sx+0.5, axisY+4); ctx.stroke();\r\n      }\r\n      if(state.grid.labels){\r\n        ctx.textAlign=\'center\';\r\n        ctx.fillText(formatNum(x), sx, axisY+16);\r\n      }\r\n    }\r\n    for(let y=sy0; y<=y0; y+=step){\r\n      if(Math.abs(y) < step/1000) continue;\r\n      const [,sy] = worldToScreen(0,y);\r\n      if(state.grid.ticks){\r\n        ctx.strokeStyle = cssVar(\'--axis\');\r\n        ctx.beginPath(); ctx.moveTo(axisX-4, sy+0.5); ctx.lineTo(axisX+4, sy+0.5); ctx.stroke();\r\n      }\r\n      if(state.grid.labels){\r\n        ctx.textAlign=\'left\';\r\n        ctx.fillText(formatNum(y), axisX+7, sy+4);\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\nfunction formatNum(n){\r\n  const r = Math.round(n*1000)/1000;\r\n  return (Math.abs(r) < 1e-9) ? \'0\' : r.toString();\r\n}\r\n\r\nfunction drawAxes(W,H){\r\n  const [ox] = worldToScreen(0,0);\r\n  const [,oy] = worldToScreen(0,0);\r\n  ctx.strokeStyle = cssVar(\'--axis\');\r\n  ctx.lineWidth = 1.6;\r\n  ctx.beginPath();\r\n  ctx.moveTo(0, oy); ctx.lineTo(W, oy);\r\n  ctx.moveTo(ox, 0); ctx.lineTo(ox, H);\r\n  ctx.stroke();\r\n  // arrows\r\n  ctx.fillStyle = cssVar(\'--axis\');\r\n  drawArrow(W-4, oy, 0);\r\n  drawArrow(ox, 4, 90);\r\n}\r\nfunction drawArrow(x,y,angleDeg){\r\n  const a = angleDeg*Math.PI/180;\r\n  ctx.save();\r\n  ctx.translate(x,y); ctx.rotate(a);\r\n  ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(-8,4); ctx.lineTo(-8,-4); ctx.closePath(); ctx.fill();\r\n  ctx.restore();\r\n}\r\n\r\nfunction drawDomainBounds(W,H){\r\n  if(state.domain.min==null && state.domain.max==null) return;\r\n}\r\n\r\nfunction drawFunction(f,W,H){\r\n  if(f.error) return;\r\n  ctx.strokeStyle = f.color;\r\n  ctx.lineWidth = f.isDerivative ? 1.8 : 2.2;\r\n  if(f.isDerivative) ctx.setLineDash([6,4]); else ctx.setLineDash([]);\r\n  ctx.beginPath();\r\n  let started = false;\r\n  let prevY = null;\r\n  const step = 1; // px\r\n  for(let px=0; px<=W; px+=step){\r\n    const [wx] = screenToWorld(px,0);\r\n    if(wx < state.domain.min || wx > state.domain.max){ started=false; continue; }\r\n    const wy = evalFn(f, wx);\r\n    if(!isFinite(wy)){ started = false; continue; }\r\n    const [, sy] = worldToScreen(wx, wy);\r\n    if(prevY !== null && Math.abs(sy - prevY) > H*2.2){ started = false; }\r\n    if(!started){ ctx.moveTo(px, sy); started = true; }\r\n    else{ ctx.lineTo(px, sy); }\r\n    prevY = sy;\r\n  }\r\n  ctx.stroke();\r\n  ctx.setLineDash([]);\r\n}\r\n\r\nfunction drawMarkers(W,H){\r\n  state.markers.forEach(m=>{\r\n    const [sx,sy] = worldToScreen(m.x, m.y);\r\n    if(sx<-20||sx>W+20||sy<-20||sy>H+20) return;\r\n    if(m.type === \'asymptote\'){\r\n      ctx.strokeStyle = m.color; ctx.setLineDash([4,4]); ctx.lineWidth=1.4;\r\n      ctx.beginPath(); ctx.moveTo(sx,0); ctx.lineTo(sx,H); ctx.stroke(); ctx.setLineDash([]);\r\n      return;\r\n    }\r\n    ctx.beginPath();\r\n    ctx.fillStyle = cssVar(\'--paper\');\r\n    ctx.arc(sx,sy,5,0,Math.PI*2); ctx.fill();\r\n    ctx.lineWidth=2; ctx.strokeStyle = m.color; ctx.stroke();\r\n    ctx.font = \'11px \' + (cssVar(\'--mono\')||\'monospace\');\r\n    ctx.fillStyle = cssVar(\'--ink\');\r\n    ctx.textAlign = \'left\';\r\n    ctx.fillText(m.label, sx+8, sy-8);\r\n  });\r\n}\r\n\r\nfunction drawIntegralShade(W,H){\r\n  const sh = state.integralShade;\r\n  if(!sh) return;\r\n  const f = state.functions.find(x=>x.id===sh.fnId);\r\n  if(!f) return;\r\n  const a = Math.min(sh.a, sh.b), b = Math.max(sh.a, sh.b);\r\n  const [sxA] = worldToScreen(a,0);\r\n  const [sxB] = worldToScreen(b,0);\r\n  const left = Math.max(0, Math.min(sxA,sxB));\r\n  const right = Math.min(W, Math.max(sxA,sxB));\r\n  if(right<=left) return;\r\n  ctx.beginPath();\r\n  const [,zeroY] = worldToScreen(0,0);\r\n  let first = true;\r\n  for(let px=left; px<=right; px++){\r\n    const [wx] = screenToWorld(px,0);\r\n    const wy = evalFn(f,wx);\r\n    const y = isFinite(wy) ? worldToScreen(wx,wy)[1] : zeroY;\r\n    if(first){ ctx.moveTo(px,y); first=false; } else ctx.lineTo(px,y);\r\n  }\r\n  ctx.lineTo(right, zeroY); ctx.lineTo(left, zeroY); ctx.closePath();\r\n  ctx.fillStyle = hexToRgba(sh.color, 0.28);\r\n  ctx.fill();\r\n}\r\nfunction hexToRgba(hex, a){\r\n  const c = hex.replace(\'#\',\'\');\r\n  const r=parseInt(c.substring(0,2),16), g=parseInt(c.substring(2,4),16), b=parseInt(c.substring(4,6),16);\r\n  return `rgba(${r},${g},${b},${a})`;\r\n}\r\n\r\nfunction drawCrosshair(W,H){\r\n  const wx = state.crosshairX, wyScreen = state.crosshairScreenY;\r\n  const [sx] = worldToScreen(wx,0);\r\n  ctx.strokeStyle = cssVar(\'--ink-soft\');\r\n  ctx.setLineDash([3,3]); ctx.lineWidth=1;\r\n  ctx.beginPath(); ctx.moveTo(sx,0); ctx.lineTo(sx,H); ctx.stroke();\r\n  ctx.beginPath(); ctx.moveTo(0,wyScreen); ctx.lineTo(W,wyScreen); ctx.stroke();\r\n  ctx.setLineDash([]);\r\n\r\n  state.functions.forEach(f=>{\r\n    if(!f.visible) return;\r\n    const wy = evalFn(f,wx);\r\n    if(!isFinite(wy)) return;\r\n    const [,sy] = worldToScreen(wx,wy);\r\n    ctx.beginPath(); ctx.fillStyle = f.color;\r\n    ctx.arc(sx,sy,4,0,Math.PI*2); ctx.fill();\r\n  });\r\n}\r\n\r\n/* ======================================================================\r\n   Sidebar: function rows\r\n====================================================================== */\r\nfunction renderFnList(){\r\n  fnList.innerHTML = \'\';\r\n  fnASel.innerHTML = \'\'; fnBSel.innerHTML = \'\';\r\n  let visibleCount = 0;\r\n  state.functions.forEach((f,idx)=>{\r\n    if(f.visible) visibleCount++;\r\n    const row = document.createElement(\'div\');\r\n    row.className = \'fnrow\' + (state.activeId===f.id ? \' active\':\'\');\r\n\r\n    const swatch = document.createElement(\'div\');\r\n    swatch.className=\'swatch\'; swatch.style.background=f.color;\r\n    swatch.title=\'Klik untuk ganti warna\';\r\n    swatch.onclick = ()=>{ f.color = palette[(palette.indexOf(f.color)+1+palette.length)%palette.length]; renderFnList(); render(); };\r\n\r\n    const label = document.createElement(\'div\');\r\n    label.className=\'fnlabel\'; label.textContent = (f.isDerivative?\"d/dx\":\'f\'+(idx+1));\r\n\r\n    const visBtn = document.createElement(\'button\');\r\n    visBtn.className=\'iconbtn\'; visBtn.title=\'Tampil/Sembunyi\';\r\n    visBtn.innerHTML = f.visible\r\n      ? \'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\'\r\n      : \'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M17.94 17.94A10.94 10.94 0 0 1 12 19c-7 0-11-7-11-7a21.6 21.6 0 0 1 5.06-5.94M9.9 4.24A10.94 10.94 0 0 1 12 4c7 0 11 7 11 7a21.6 21.6 0 0 1-2.16 3.19M1 1l22 22\"/></svg>\';\r\n    visBtn.onclick = ()=>{ f.visible=!f.visible; renderFnList(); render(); };\r\n\r\n    const input = document.createElement(\'input\');\r\n    input.type=\'text\'; input.value=f.raw; input.spellcheck=false;\r\n    input.placeholder=\'mis. x^2 - 3*x + 1\';\r\n    input.onfocus = ()=>{ state.activeId=f.id; renderFnList(); };\r\n    input.oninput = ()=>{ f.raw=input.value; compileFn(f); renderPretty(); renderParams(); renderFnASelectors(); render(); };\r\n\r\n    const delBtn = document.createElement(\'button\');\r\n    delBtn.className=\'iconbtn\'; delBtn.title=\'Hapus\';\r\n    delBtn.innerHTML = \'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6h14z\"/></svg>\';\r\n    delBtn.onclick = ()=>{\r\n      state.functions = state.functions.filter(x=>x.id!==f.id);\r\n      if(state.activeId===f.id) state.activeId = state.functions[0]?.id || null;\r\n      state.markers = state.markers.filter(m=>m.fnId!==f.id);\r\n      renderFnList(); render();\r\n    };\r\n\r\n    row.appendChild(swatch); row.appendChild(label); row.appendChild(visBtn); row.appendChild(input); row.appendChild(delBtn);\r\n    fnList.appendChild(row);\r\n\r\n    const pretty = document.createElement(\'div\');\r\n    pretty.className=\'fnpretty\';\r\n    pretty.textContent = f.error ? (\'⚠ \' + f.error) : (\'y = \' + prettify(f.raw||\'\'));\r\n    if(f.error) pretty.style.color = \'var(--danger)\';\r\n    fnList.appendChild(pretty);\r\n\r\n    const dom = document.createElement(\'div\');\r\n    dom.className=\'fndomain\';\r\n    const dmin = document.createElement(\'input\'); dmin.type=\'number\'; dmin.placeholder=\'domain min\';\r\n    dmin.value = f.domainMin ?? \'\';\r\n    dmin.oninput = ()=>{ f.domainMin = dmin.value===\'\'?null:parseFloat(dmin.value); render(); };\r\n    const dmax = document.createElement(\'input\'); dmax.type=\'number\'; dmax.placeholder=\'domain max\';\r\n    dmax.value = f.domainMax ?? \'\';\r\n    dmax.oninput = ()=>{ f.domainMax = dmax.value===\'\'?null:parseFloat(dmax.value); render(); };\r\n    dom.appendChild(dmin); dom.appendChild(dmax);\r\n    fnList.appendChild(dom);\r\n  });\r\n  fnCount.textContent = visibleCount + \' aktif\';\r\n  renderFnASelectors();\r\n}\r\n\r\nfunction renderFnASelectors(){\r\n  const cur = fnASel.value, curB = fnBSel.value;\r\n  fnASel.innerHTML=\'\'; fnBSel.innerHTML=\'\';\r\n  state.functions.forEach((f,idx)=>{\r\n    const label = (f.isDerivative?\"d/dx \":\'f\'+(idx+1)+\': \') + f.raw;\r\n    const optA = document.createElement(\'option\'); optA.value=f.id; optA.textContent=label;\r\n    const optB = document.createElement(\'option\'); optB.value=f.id; optB.textContent=label;\r\n    fnASel.appendChild(optA); fnBSel.appendChild(optB);\r\n  });\r\n  if([...fnASel.options].some(o=>o.value===cur)) fnASel.value=cur;\r\n  if([...fnBSel.options].some(o=>o.value===curB)) fnBSel.value=curB;\r\n}\r\n\r\nfunction renderPretty(){\r\n  // triggered on input; full list already rebuilt via renderFnList on structural changes\r\n}\r\n\r\n/* ======================================================================\r\n   Params / sliders\r\n====================================================================== */\r\nfunction renderParams(){\r\n  const names = Object.keys(state.params);\r\n  paramsSection.style.display = names.length? \'block\':\'none\';\r\n  paramList.innerHTML=\'\';\r\n  names.forEach(n=>{\r\n    const cfg = state.paramCfg[n] || {min:-10,max:10,step:0.1};\r\n    const row = document.createElement(\'div\'); row.className=\'paramrow\';\r\n    const label = document.createElement(\'div\'); label.className=\'paramname\'; label.textContent=n;\r\n    const range = document.createElement(\'input\'); range.type=\'range\';\r\n    range.min=cfg.min; range.max=cfg.max; range.step=cfg.step; range.value=state.params[n];\r\n    const val = document.createElement(\'div\'); val.className=\'paramval\'; val.textContent=state.params[n];\r\n    range.oninput = ()=>{ state.params[n]=parseFloat(range.value); val.textContent = state.params[n].toFixed(2); render(); };\r\n    row.appendChild(label); row.appendChild(range); row.appendChild(val);\r\n    paramList.appendChild(row);\r\n  });\r\n}\r\n\r\n/* ======================================================================\r\n   Add / library\r\n====================================================================== */\r\nfunction addFunction(expr){\r\n  const f = makeFn(expr || \'\');\r\n  state.functions.push(f);\r\n  state.activeId = f.id;\r\n  renderFnList(); render();\r\n  return f;\r\n}\r\ndocument.getElementById(\'addFn\').onclick = ()=> addFunction(\'\');\r\n\r\nconst LIB = {\r\n  Aljabar: [[\'Kuadrat\',\'x^2\'],[\'Kubik\',\'x^3 - 2*x\'],[\'Rasional\',\'1/x\'],[\'Akar\',\'sqrt(x)\'],[\'Nilai mutlak\',\'abs(x)\']],\r\n  Trig: [[\'sin\',\'sin(x)\'],[\'cos\',\'cos(x)\'],[\'tan\',\'tan(x)\'],[\'sin·cos\',\'sin(x)*cos(2*x)\']],\r\n  Log: [[\'ln\',\'ln(x)\'],[\'log10\',\'log10(x)\'],[\'exp\',\'exp(x)\'],[\'2^x\',\'2^x\']],\r\n  Piece: [[\'Piecewise\',\'x<0 ? -x : x^2\'],[\'Tangga\',\'x<0 ? -1 : (x==0 ? 0 : 1)\']]\r\n};\r\nfunction fillLib(containerId, items){\r\n  const c = document.getElementById(containerId);\r\n  items.forEach(([label,expr])=>{\r\n    const b = document.createElement(\'button\'); b.className=\'libbtn\'; b.textContent=label;\r\n    b.onclick = ()=> addFunction(expr);\r\n    c.appendChild(b);\r\n  });\r\n}\r\nfillLib(\'libAljabar\', LIB.Aljabar);\r\nfillLib(\'libTrig\', LIB.Trig);\r\nfillLib(\'libLog\', LIB.Log);\r\nfillLib(\'libPiece\', LIB.Piece);\r\n\r\ndocument.getElementById(\'angleMode\').onchange = (e)=>{ state.angleMode = e.target.value; render(); };\r\n\r\n/* ======================================================================\r\n   Numeric analysis helpers\r\n====================================================================== */\r\nfunction sampleRange(){ return [state.domain.min, state.domain.max]; }\r\n\r\nfunction bisect(fn, a, b, iters=40){\r\n  let fa = fn(a);\r\n  for(let i=0;i<iters;i++){\r\n    const m = (a+b)/2, fm = fn(m);\r\n    if(fa*fm <= 0){ b=m; } else { a=m; fa=fm; }\r\n  }\r\n  return (a+b)/2;\r\n}\r\n\r\nfunction findRoots(f){\r\n  const [a,b] = sampleRange();\r\n  const N = 3000, dx=(b-a)/N;\r\n  let prevX=a, prevY=evalFn(f,a);\r\n  const roots=[];\r\n  for(let i=1;i<=N;i++){\r\n    const x=a+i*dx, y=evalFn(f,x);\r\n    if(isFinite(prevY) && isFinite(y)){\r\n      if(prevY===0){ roots.push(prevX); }\r\n      else if(prevY*y<0){\r\n        const r = bisect(v=>evalFn(f,v), prevX, x);\r\n        roots.push(r);\r\n      }\r\n    }\r\n    prevX=x; prevY=y;\r\n  }\r\n  return roots;\r\n}\r\n\r\nfunction derivativeOf(f){\r\n  try{\r\n    const dnode = math.derivative(f.node, \'x\');\r\n    return dnode.compile();\r\n  }catch(e){ return null; }\r\n}\r\n\r\nfunction findExtrema(f){\r\n  const dcomp = derivativeOf(f);\r\n  if(!dcomp) return [];\r\n  const dEval = (x)=>{\r\n    try{\r\n      const v = dcomp.evaluate(evalScope(x));\r\n      return (typeof v===\'number\' && isFinite(v)) ? v : NaN;\r\n    }catch(e){ return NaN; }\r\n  };\r\n  const [a,b] = sampleRange();\r\n  const N=3000, dx=(b-a)/N;\r\n  let prevX=a, prevY=dEval(a);\r\n  const out=[];\r\n  for(let i=1;i<=N;i++){\r\n    const x=a+i*dx, y=dEval(x);\r\n    if(isFinite(prevY)&&isFinite(y)&&prevY*y<0){\r\n      const r = bisect(v=>dEval(v), prevX, x);\r\n      const type = (prevY>0 && y<0) ? \'max\' : \'min\';\r\n      out.push({x:r, y:evalFn(f,r), type});\r\n    }\r\n    prevX=x; prevY=y;\r\n  }\r\n  return out;\r\n}\r\n\r\nfunction findIntersections(fA,fB){\r\n  const h = (x)=> evalFn(fA,x)-evalFn(fB,x);\r\n  const [a,b] = sampleRange();\r\n  const N=3000, dx=(b-a)/N;\r\n  let prevX=a, prevY=h(a);\r\n  const out=[];\r\n  for(let i=1;i<=N;i++){\r\n    const x=a+i*dx, y=h(x);\r\n    if(isFinite(prevY)&&isFinite(y)&&prevY*y<0){\r\n      const r = bisect(h, prevX, x);\r\n      out.push({x:r, y:evalFn(fA,r)});\r\n    }\r\n    prevX=x; prevY=y;\r\n  }\r\n  return out;\r\n}\r\n\r\nfunction findAsymptotes(f){\r\n  const [a,b] = sampleRange();\r\n  const N=1500, dx=(b-a)/N;\r\n  const out=[];\r\n  let prevY = evalFn(f,a);\r\n  for(let i=1;i<=N;i++){\r\n    const x=a+i*dx, y=evalFn(f,x);\r\n    const prevFinite = isFinite(prevY), curFinite = isFinite(y);\r\n    if((prevFinite && !curFinite) || (!prevFinite && curFinite) || (prevFinite&&curFinite&&Math.abs(y-prevY)>1e4)){\r\n      out.push(x-dx/2);\r\n    }\r\n    prevY=y;\r\n  }\r\n  return out;\r\n}\r\n\r\nfunction simpsonIntegral(f,a,b,n=400){\r\n  if(n%2!==0) n++;\r\n  const h=(b-a)/n;\r\n  let sum = evalFnSafe(f,a)+evalFnSafe(f,b);\r\n  for(let i=1;i<n;i++){\r\n    const x=a+i*h;\r\n    sum += (i%2===0?2:4)*evalFnSafe(f,x);\r\n  }\r\n  return sum*h/3;\r\n}\r\nfunction evalFnSafe(f,x){ const v=evalFn(f,x); return isFinite(v)?v:0; }\r\n\r\n/* ======================================================================\r\n   Results log\r\n====================================================================== */\r\nfunction logResult(color, text){\r\n  const div = document.createElement(\'div\'); div.className=\'logitem\';\r\n  div.innerHTML = `<span style=\"display:flex;gap:6px;align-items:flex-start;\"><span class=\"swatch2\" style=\"background:${color}\"></span><span>${text}</span></span>`;\r\n  resultsLog.prepend(div);\r\n}\r\nfunction addMarker(x,y,label,color,type=\'point\', fnId=null){\r\n  state.markers.push({x,y,label,color,type,fnId});\r\n}\r\n\r\n/* ======================================================================\r\n   Toolbar / analysis actions\r\n====================================================================== */\r\nfunction activeFn(){ return state.functions.find(f=>f.id===state.activeId) || state.functions[0]; }\r\nfunction fnById(id){ return state.functions.find(f=>f.id===id); }\r\n\r\ndocument.getElementById(\'actRoots\').onclick = ()=>{\r\n  const f = fnById(fnASel.value); if(!f||f.error) return toast(\'Pilih fungsi yang valid\');\r\n  const roots = findRoots(f);\r\n  if(!roots.length) return toast(\'Tidak ditemukan akar pada rentang domain ini\');\r\n  roots.forEach(r=>{ addMarker(r,0,\'x≈\'+r.toFixed(3),f.color); logResult(f.color, \'Akar: x ≈ \'+r.toFixed(4)); });\r\n  render(); toast(roots.length+\' akar ditemukan\');\r\n};\r\ndocument.getElementById(\'btnRoots\').onclick = ()=> document.getElementById(\'actRoots\').click();\r\n\r\ndocument.getElementById(\'actExtrema\').onclick = ()=>{\r\n  const f = fnById(fnASel.value); if(!f||f.error) return toast(\'Pilih fungsi yang valid\');\r\n  const ext = findExtrema(f);\r\n  if(!ext.length) return toast(\'Tidak ditemukan ekstrem pada rentang domain ini\');\r\n  ext.forEach(e=>{\r\n    const lab=(e.type===\'max\'?\'Maks\':\'Min\')+\' (\'+e.x.toFixed(2)+\', \'+e.y.toFixed(2)+\')\';\r\n    addMarker(e.x,e.y,lab,f.color);\r\n    logResult(f.color, (e.type===\'max\'?\'Maksimum\':\'Minimum\')+\': (\'+e.x.toFixed(4)+\', \'+e.y.toFixed(4)+\')\');\r\n  });\r\n  render(); toast(ext.length+\' titik ekstrem ditemukan\');\r\n};\r\ndocument.getElementById(\'btnExtrema\').onclick = ()=> document.getElementById(\'actExtrema\').click();\r\n\r\ndocument.getElementById(\'actIntersect\').onclick = ()=>{\r\n  const fA = fnById(fnASel.value), fB = fnById(fnBSel.value);\r\n  if(!fA||!fB||fA.error||fB.error) return toast(\'Pilih dua fungsi yang valid\');\r\n  if(fA.id===fB.id) return toast(\'Pilih dua fungsi yang berbeda\');\r\n  const pts = findIntersections(fA,fB);\r\n  if(!pts.length) return toast(\'Tidak ditemukan perpotongan\');\r\n  pts.forEach(p=>{\r\n    addMarker(p.x,p.y,\'(\'+p.x.toFixed(2)+\', \'+p.y.toFixed(2)+\')\', \'#8b5cf6\');\r\n    logResult(\'#8b5cf6\', \'Interseksi: (\'+p.x.toFixed(4)+\', \'+p.y.toFixed(4)+\')\');\r\n  });\r\n  render(); toast(pts.length+\' titik interseksi ditemukan\');\r\n};\r\n\r\ndocument.getElementById(\'actAsymp\').onclick = ()=>{\r\n  const f = fnById(fnASel.value); if(!f||f.error) return toast(\'Pilih fungsi yang valid\');\r\n  const asym = findAsymptotes(f);\r\n  if(!asym.length) return toast(\'Tidak ditemukan asimtot vertikal yang jelas\');\r\n  asym.forEach(x=>{\r\n    addMarker(x,0,\'x≈\'+x.toFixed(2), \'#94a3b8\',\'asymptote\');\r\n    logResult(f.color, \'Asimtot vertikal: x ≈ \'+x.toFixed(4));\r\n  });\r\n  render(); toast(asym.length+\' asimtot terdeteksi\');\r\n};\r\n\r\ndocument.getElementById(\'actDeriv\').onclick = ()=>{\r\n  const f = fnById(fnASel.value); if(!f||f.error) return toast(\'Pilih fungsi yang valid\');\r\n  try{\r\n    const dnode = math.derivative(f.node,\'x\');\r\n    const derivFn = makeFn(dnode.toString(), {isDerivative:true, color:f.color});\r\n    state.functions.push(derivFn);\r\n    renderFnList(); render();\r\n    toast(\'Turunan ditambahkan sebagai plot putus-putus\');\r\n  }catch(e){ toast(\'Gagal menghitung turunan (mungkin ada piecewise)\'); }\r\n};\r\ndocument.getElementById(\'btnDeriv\').onclick = ()=> document.getElementById(\'actDeriv\').click();\r\n\r\ndocument.getElementById(\'actIntegral\').onclick = ()=>{\r\n  const f = fnById(fnASel.value); if(!f||f.error) return toast(\'Pilih fungsi yang valid\');\r\n  const a = parseFloat(document.getElementById(\'intA\').value);\r\n  const b = parseFloat(document.getElementById(\'intB\').value);\r\n  if(!isFinite(a)||!isFinite(b)||a===b) return toast(\'Masukkan batas a dan b yang valid\');\r\n  const val = simpsonIntegral(f, Math.min(a,b), Math.max(a,b));\r\n  state.integralShade = {fnId:f.id, a, b, color:f.color, value:val};\r\n  logResult(f.color, \'∫ dari \'+a+\' ke \'+b+\' ≈ \'+val.toFixed(5));\r\n  render(); toast(\'Luas ≈ \'+val.toFixed(5));\r\n};\r\ndocument.getElementById(\'btnIntegral\').onclick = ()=> document.getElementById(\'actIntegral\').click();\r\n\r\ndocument.getElementById(\'clearMarkers\').onclick = ()=>{\r\n  state.markers = []; state.integralShade=null; resultsLog.innerHTML=\'\'; render(); toast(\'Penanda dibersihkan\');\r\n};\r\n\r\n/* ======================================================================\r\n   Grid options\r\n====================================================================== */\r\nfunction syncGridChecks(){\r\n  document.getElementById(\'chkGrid\').checked = state.grid.lines;\r\n  document.getElementById(\'chkAxes\').checked = state.grid.axes;\r\n  document.getElementById(\'chkLabels\').checked = state.grid.labels;\r\n  document.getElementById(\'chkTicks\').checked = state.grid.ticks;\r\n}\r\ndocument.getElementById(\'chkGrid\').onchange = e=>{ state.grid.lines=e.target.checked; render(); };\r\ndocument.getElementById(\'chkAxes\').onchange = e=>{ state.grid.axes=e.target.checked; render(); };\r\ndocument.getElementById(\'chkLabels\').onchange = e=>{ state.grid.labels=e.target.checked; render(); };\r\ndocument.getElementById(\'chkTicks\').onchange = e=>{ state.grid.ticks=e.target.checked; render(); };\r\ndocument.getElementById(\'btnGrid\').onclick = ()=>{\r\n  state.grid.lines = !state.grid.lines; syncGridChecks(); render();\r\n};\r\n\r\ndocument.getElementById(\'domMin\').oninput = e=>{ state.domain.min=parseFloat(e.target.value)||-20; render(); };\r\ndocument.getElementById(\'domMax\').oninput = e=>{ state.domain.max=parseFloat(e.target.value)||20; render(); };\r\n\r\n/* ======================================================================\r\n   View controls: zoom / drag / reset / center\r\n====================================================================== */\r\nfunction zoomAt(px,py,factor){\r\n  const [wx,wy] = screenToWorld(px,py);\r\n  state.view.scale = Math.min(4000, Math.max(2, state.view.scale*factor));\r\n  const [nwx,nwy] = screenToWorld(px,py);\r\n  state.view.ox += (wx-nwx);\r\n  state.view.oy += (wy-nwy);\r\n  render();\r\n}\r\ncanvas.addEventListener(\'wheel\', (e)=>{\r\n  e.preventDefault();\r\n  const rect = canvas.getBoundingClientRect();\r\n  const px = e.clientX-rect.left, py = e.clientY-rect.top;\r\n  const factor = e.deltaY < 0 ? 1.12 : 1/1.12;\r\n  zoomAt(px,py,factor);\r\n}, {passive:false});\r\n\r\nlet dragging=false, lastPX=0, lastPY=0, moved=false;\r\ncanvas.addEventListener(\'mousedown\', (e)=>{\r\n  dragging=true; moved=false; canvas.classList.add(\'dragging\');\r\n  lastPX=e.clientX; lastPY=e.clientY;\r\n});\r\nwindow.addEventListener(\'mousemove\', (e)=>{\r\n  const rect = canvas.getBoundingClientRect();\r\n  const px = e.clientX-rect.left, py = e.clientY-rect.top;\r\n  if(dragging){\r\n    const dx = e.clientX-lastPX, dy = e.clientY-lastPY;\r\n    if(Math.abs(dx)+Math.abs(dy) > 2) moved = true;\r\n    state.view.ox -= dx/state.view.scale;\r\n    state.view.oy += dy/state.view.scale;\r\n    lastPX=e.clientX; lastPY=e.clientY;\r\n    updateCrosshair(px,py);\r\n    render();\r\n  } else if(px>=0 && py>=0 && px<=cssW() && py<=cssH()){\r\n    updateCrosshair(px,py);\r\n    render();\r\n  }\r\n});\r\nwindow.addEventListener(\'mouseup\', ()=>{ dragging=false; canvas.classList.remove(\'dragging\'); });\r\ncanvas.addEventListener(\'mouseleave\', ()=>{ hud.style.display=\'none\'; state.crosshairX=undefined; render(); });\r\n\r\n// touch support (drag + pinch zoom)\r\nlet touchState = {mode:null, lastDist:0, lastX:0, lastY:0};\r\ncanvas.addEventListener(\'touchstart\', (e)=>{\r\n  if(e.touches.length===1){\r\n    touchState.mode=\'pan\'; touchState.lastX=e.touches[0].clientX; touchState.lastY=e.touches[0].clientY;\r\n  } else if(e.touches.length===2){\r\n    touchState.mode=\'zoom\';\r\n    touchState.lastDist = touchDist(e.touches);\r\n  }\r\n}, {passive:true});\r\ncanvas.addEventListener(\'touchmove\', (e)=>{\r\n  e.preventDefault();\r\n  if(touchState.mode===\'pan\' && e.touches.length===1){\r\n    const dx = e.touches[0].clientX - touchState.lastX;\r\n    const dy = e.touches[0].clientY - touchState.lastY;\r\n    state.view.ox -= dx/state.view.scale;\r\n    state.view.oy += dy/state.view.scale;\r\n    touchState.lastX = e.touches[0].clientX; touchState.lastY = e.touches[0].clientY;\r\n    render();\r\n  } else if(touchState.mode===\'zoom\' && e.touches.length===2){\r\n    const d = touchDist(e.touches);\r\n    const rect = canvas.getBoundingClientRect();\r\n    const cx = (e.touches[0].clientX+e.touches[1].clientX)/2 - rect.left;\r\n    const cy = (e.touches[0].clientY+e.touches[1].clientY)/2 - rect.top;\r\n    zoomAt(cx,cy, d/touchState.lastDist);\r\n    touchState.lastDist = d;\r\n  }\r\n}, {passive:false});\r\ncanvas.addEventListener(\'touchend\', ()=>{ touchState.mode=null; });\r\nfunction touchDist(t){ return Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY); }\r\n\r\nfunction updateCrosshair(px,py){\r\n  const [wx] = screenToWorld(px,py);\r\n  state.crosshairX = wx;\r\n  state.crosshairScreenY = py;\r\n  hud.style.display=\'block\';\r\n  const nearest = state.functions.filter(f=>f.visible).map((f,i)=>{\r\n    const y = evalFn(f, wx);\r\n    return {color:f.color, y};\r\n  });\r\n  let html = `<div class=\"hrow\"><span>x =</span><span class=\"hx\">${wx.toFixed(3)}</span></div>`;\r\n  const [,wy] = screenToWorld(px,py);\r\n  html += `<div class=\"hrow\"><span>y =</span><span class=\"hy\">${wy.toFixed(3)}</span></div>`;\r\n  nearest.forEach((n,i)=>{\r\n    html += `<div class=\"hrow\"><span style=\"color:${n.color}\">f${i+1}(x)</span><span>${isFinite(n.y)?n.y.toFixed(3):\'—\'}</span></div>`;\r\n  });\r\n  hud.innerHTML = html;\r\n}\r\n\r\ndocument.getElementById(\'btnZoomIn\').onclick = ()=> zoomAt(cssW()/2, cssH()/2, 1.3);\r\ndocument.getElementById(\'btnZoomOut\').onclick = ()=> zoomAt(cssW()/2, cssH()/2, 1/1.3);\r\ndocument.getElementById(\'btnReset\').onclick = ()=>{\r\n  state.view = {scale:40, ox:0, oy:0}; render(); toast(\'Tampilan direset\');\r\n};\r\ndocument.getElementById(\'btnCenter\').onclick = ()=>{\r\n  state.view.ox = 0; state.view.oy = 0; render(); toast(\'Dipusatkan ke origin\');\r\n};\r\n\r\n/* ======================================================================\r\n   Dark mode\r\n====================================================================== */\r\nfunction setDark(on){\r\n  state.dark = on;\r\n  document.body.setAttribute(\'data-theme\', on?\'dark\':\'light\');\r\n  render();\r\n}\r\ndocument.getElementById(\'btnDark\').onclick = ()=> setDark(!state.dark);\r\n\r\n/* ======================================================================\r\n   Export: save image / share link / CSV table\r\n====================================================================== */\r\ndocument.getElementById(\'btnSave\').onclick = ()=>{\r\n  canvas.toBlob(blob=>{\r\n    const url = URL.createObjectURL(blob);\r\n    const a = document.createElement(\'a\');\r\n    a.href=url; a.download=\'grafik.png\'; a.click();\r\n    URL.revokeObjectURL(url);\r\n    toast(\'Gambar disimpan\');\r\n  });\r\n};\r\n\r\ndocument.getElementById(\'btnShare\').onclick = ()=>{\r\n  const payload = {\r\n    fns: state.functions.filter(f=>!f.isDerivative).map(f=>({raw:f.raw,color:f.color,visible:f.visible,domainMin:f.domainMin,domainMax:f.domainMax})),\r\n    params: state.params, paramCfg: state.paramCfg, view: state.view, grid: state.grid, dark: state.dark,\r\n    domain: state.domain, angleMode: state.angleMode\r\n  };\r\n  try{\r\n    const encoded = btoa(encodeURIComponent(JSON.stringify(payload)));\r\n    const url = location.origin + location.pathname + \'#state=\' + encoded;\r\n    if(navigator.clipboard){\r\n      navigator.clipboard.writeText(url).then(()=> toast(\'Tautan disalin ke clipboard\')).catch(()=>{\r\n        prompt(\'Salin tautan ini:\', url);\r\n      });\r\n    } else {\r\n      prompt(\'Salin tautan ini:\', url);\r\n    }\r\n  }catch(e){ toast(\'Gagal membuat tautan berbagi\'); }\r\n};\r\n\r\nfunction loadFromHash(){\r\n  const h = location.hash;\r\n  if(!h.startsWith(\'#state=\')) return false;\r\n  try{\r\n    const json = decodeURIComponent(atob(h.slice(7)));\r\n    const payload = JSON.parse(json);\r\n    state.functions = [];\r\n    (payload.fns||[]).forEach(f=>{\r\n      const nf = makeFn(f.raw, {color:f.color, domainMin:f.domainMin, domainMax:f.domainMax});\r\n      nf.visible = f.visible;\r\n      state.functions.push(nf);\r\n    });\r\n    if(payload.params) state.params = payload.params;\r\n    if(payload.paramCfg) state.paramCfg = payload.paramCfg;\r\n    if(payload.view) state.view = payload.view;\r\n    if(payload.grid) state.grid = payload.grid;\r\n    if(payload.domain) state.domain = payload.domain;\r\n    if(payload.angleMode) state.angleMode = payload.angleMode;\r\n    document.getElementById(\'angleMode\').value = state.angleMode;\r\n    document.getElementById(\'domMin\').value = state.domain.min;\r\n    document.getElementById(\'domMax\').value = state.domain.max;\r\n    setDark(!!payload.dark);\r\n    syncGridChecks();\r\n    state.activeId = state.functions[0]?.id || null;\r\n    renderFnList(); renderParams();\r\n    toast(\'Grafik dimuat dari tautan berbagi\');\r\n    return true;\r\n  }catch(e){ return false; }\r\n}\r\n\r\ndocument.getElementById(\'exportTable\').onclick = ()=>{\r\n  const f = fnById(fnASel.value);\r\n  if(!f||f.error) return toast(\'Pilih fungsi yang valid untuk diekspor\');\r\n  const [a,b] = sampleRange();\r\n  const n = 50; const dx=(b-a)/n;\r\n  let csv = \'x,y\\n\';\r\n  for(let i=0;i<=n;i++){\r\n    const x=a+i*dx, y=evalFn(f,x);\r\n    csv += x.toFixed(4)+\',\'+(isFinite(y)?y.toFixed(6):\'\')+\'\\n\';\r\n  }\r\n  const blob = new Blob([csv], {type:\'text/csv\'});\r\n  const url = URL.createObjectURL(blob);\r\n  const a2 = document.createElement(\'a\'); a2.href=url; a2.download=\'tabel-nilai.csv\'; a2.click();\r\n  URL.revokeObjectURL(url);\r\n  toast(\'Tabel nilai diekspor sebagai CSV\');\r\n};\r\n\r\n/* ======================================================================\r\n   Demo loader\r\n====================================================================== */\r\ndocument.getElementById(\'loadDemo\').onclick = ()=>{\r\n  state.functions = [];\r\n  colorIdx = 0;\r\n  addFunction(\'a*sin(b*x)\');\r\n  addFunction(\'x^2/8 - 2\');\r\n  addFunction(\'1/x\');\r\n  ensureParams([\'a\',\'b\']);\r\n  state.params.a = 3; state.params.b = 1;\r\n  renderParams();\r\n  toast(\'Contoh grafik dimuat — coba geser slider a dan b\');\r\n};\r\n\r\n/* ======================================================================\r\n   Sidebar toggle (mobile)\r\n====================================================================== */\r\nconst sidebar = document.getElementById(\'sidebar\');\r\ndocument.getElementById(\'sidebarToggle\').onclick = ()=> sidebar.classList.toggle(\'open\');\r\ncanvasWrap.addEventListener(\'mousedown\', ()=>{ if(window.innerWidth<=860) sidebar.classList.remove(\'open\'); });\r\n\r\n/* ======================================================================\r\n   Keyboard shortcuts\r\n====================================================================== */\r\nwindow.addEventListener(\'keydown\', (e)=>{\r\n  if(e.target.tagName===\'INPUT\' || e.target.tagName===\'SELECT\') return;\r\n  if(e.key===\'+\' || e.key===\'=\') zoomAt(cssW()/2, cssH()/2, 1.2);\r\n  else if(e.key===\'-\' || e.key===\'_\') zoomAt(cssW()/2, cssH()/2, 1/1.2);\r\n  else if(e.key===\'d\' || e.key===\'D\') setDark(!state.dark);\r\n  else if(e.key===\'r\' || e.key===\'R\'){ state.view={scale:40,ox:0,oy:0}; render(); }\r\n});\r\n\r\n/* ======================================================================\r\n   Init\r\n====================================================================== */\r\nfunction init(){\r\n  syncGridChecks();\r\n  if(!loadFromHash()){\r\n    addFunction(\'x^2\');\r\n    addFunction(\'sin(x)\');\r\n  }\r\n  resizeCanvas();\r\n  render();\r\n}\r\nwindow.addEventListener(\'load\', ()=>{ setTimeout(resizeCanvas, 30); });\r\ninit();\r\n\r\n})();\r\n</script>\r\n</body>\r\n</html>','2026-08-03 05:36:34','2026-08-03 05:36:34');
